style.css:
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow-x: hidden; /* prevent scrollbars from drifting shapes */
}

body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;
  background: linear-gradient(135deg, #ff9a9e, #fad0c4, #fbc2eb, #a18cd1);
  background-size: 400% 400%;
  animation: gradientShift 15s ease infinite;
}

/* Floating glowing circles */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  z-index: -1;
  pointer-events: none; /* don’t interfere with clicks */

  background-image: radial-gradient(rgba(255,255,255,0.3) 20%, transparent 60%),
                    radial-gradient(rgba(255,182,193,0.25) 20%, transparent 60%),
                    radial-gradient(rgba(255,255,255,0.2) 20%, transparent 60%),
                    radial-gradient(rgba(255,182,193,0.15) 20%, transparent 60%);
  background-size: 300px 300px, 400px 400px, 500px 500px, 600px 600px;
  background-position: 0 0, 50% 50%, 100% 100%, 25% 75%;

  animation: floatShapes 60s linear infinite;
}

@keyframes gradientShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes floatShapes {
  0%   { transform: translate(0, 0); }
  50%  { transform: translate(-100px, -200px); }
  100% { transform: translate(0, 0); }
}
